CREATE VIEW [RegsBI].[vwClientsMoney]
AS
SELECT 
	[FirmNumber],
	[FirmName],
	[AnnualReturn],
	[Latest Annual Return],
	[Max Clients Money Last 12 Months],
	[Estimated Avg Clients Money Last 12 Months],
	[Auction or farm sale account],
	[Discrete or designated accounts],
	[General client account],
	[Loss of Clients Money 12 Months],
	[Has your firm experienced any difficulties in obtaining a client account],
	[Please provide further information (difficulties in obtaining a client account)],
	[Is all clients' money held by your firm],
	[Please provide further information on where the money is collected and where it is held],
	[Does your firm hold clients' money in residential lettings and residential property management activities in England only],
	[Accounts not wholly controlled by the firm],
	[When did your firm start holding clients' money],
	[Tenancy Deposit Protection Schemes - Lettings Protection Service Scotland],
	[Tenancy Deposit Protection Schemes - Letting Protection Service Northern Ireland (LPSNI)],
	[Tenancy Deposit Protection Schemes - My Deposits],
	[Tenancy Deposit Protection Schemes - My Deposits Northern Ireland],
	[Tenancy Deposit Protection Schemes - My Deposits Scotand],
	[Tenancy Deposit Protection Schemes - No new deposits since introduction of legislation],
	[Tenancy Deposit Protection Schemes - Safe Deposits Scotland],
	[Tenancy Deposit Protection Schemes - The Tenancy Deposit Scheme (TDS) operated by The Dispute Service Limited],
	[Tenancy Deposit Protection Schemes - Tenancy Deposit Scheme Northern Ireland (TDS)],
	[Tenancy Deposit Protection Schemes - The Deposit Protection Service],
	[Does your firm hold tenancy deposits in relation to assured shorthold tenancy lettings],
	[Is all clients' money held in an account with "client" in the title],
	[Does your firm hold tenancy deposits in relation to assured shorthold tenancy lettings within England and Wales],
	[If yes which of the following schemes is your firm Registered with],
	[Does your firm hold tenancy deposits in relation to assured shorthold tenancy lettings within Scotland],
	[If yes, which of the following schemes is your firm Registered with],
	[Does your firm hold clients' money],
	[If your firm started holding clients' money in the last 12 months, please enter the date],
	[Maximum amount of money held for all clients' at any one time in the last twelve months],
	[What was the estimated average amount of clients' money held for all clients at any one time in the past twelve months],
	[How many clients does your firm hold money for],
	[How many client bank accounts does your firm operate Please state the number of client accounts held in each category],
	[General client bank accounts],
	[Discrete or designated client bank accounts],
	[Auction or Farm Sale bank accounts],
	[Bank accounts not wholly controlled by the firm ( such as where the client is a signatory on the account)],
	[LPA receivership bank accounts],
	[Livestock Auctioneer bank accounts],
	[What was the approximate total number of receipts and payments processed through all client accounts in the last twelve months],
	[Has there been any loss of clients' money as a result of theft, misappropriation or accounting errors in the last twelve months],
	[If yes, please provide details of the loss],
	[Has the clients' money been reinstated from the office account or other source],
	[Is there, or has there been, any surplus money in the client account relating to clients who cannot be traced],
	[If the firm ceased holding clients' money in the last 12 months, please enter the date]
FROM [Ext].[PBI02_RegsBI_vwClientsMoney]
